const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometries
  const namibia = ee.Geometry.Polygon([[
    [11.73, -17.08], [25.26, -17.08], [25.26, -28.97], [11.73, -28.97], [11.73, -17.08]
  ]]);

  const zimbabwe = ee.Geometry.Polygon([[
    [25.26, -15.62], [32.83, -15.62], [32.83, -22.41], [25.26, -22.41], [25.26, -15.62]
  ]]);

  // Helper function to calculate NDVI
  function addNDVI(img) {
    return img.normalizedDifference(['B5', 'B4']).rename('NDVI').copyProperties(img, ['system:time_start']);
  }

  // Function to mask clouds in Landsat
  function maskClouds(img) {
    const qa = img.select('BQA');
    const cloud = qa.bitwiseAnd(1 << 4).eq(0);
    return img.updateMask(cloud);
  }

  // Get Feb 21-28 2019 data
  const feb2019Start = ee.Date('2019-02-21');
  const feb2019End = ee.Date('2019-02-28');

  // Get Landsat 8 collections for both locations
  const ls8_2019_nam = ee.ImageCollection('LANDSAT/LC08/C01/T1_TOA')
    .filterDate(feb2019Start, feb2019End)
    .filterBounds(namibia)
    .map(maskClouds)
    .map(addNDVI);

  const ls8_2019_zim = ee.ImageCollection('LANDSAT/LC08/C01/T1_TOA')
    .filterDate(feb2019Start, feb2019End)
    .filterBounds(zimbabwe)
    .map(maskClouds)
    .map(addNDVI);

  // Get baseline Feb 21-28 data (2003-2017)
  let baseline_nam = ee.ImageCollection('LANDSAT/LE07/C01/T1_TOA')
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .filter(ee.Filter.calendarRange(21, 28, 'day_of_year'))
    .filter(ee.Filter.calendarRange(2003, 2017, 'year'))
    .filterBounds(namibia)
    .map(maskClouds)
    .map(addNDVI);

  let baseline_zim = ee.ImageCollection('LANDSAT/LE07/C01/T1_TOA')
    .filter(ee.Filter.calendarRange(2, 2, 'month'))
    .filter(ee.Filter.calendarRange(21, 28, 'day_of_year'))
    .filter(ee.Filter.calendarRange(2003, 2017, 'year'))
    .filterBounds(zimbabwe)
    .map(maskClouds)
    .map(addNDVI);

  // Check data availability
  const size_2019_nam = ls8_2019_nam.size().getInfo();
  const size_2019_zim = ls8_2019_zim.size().getInfo();
  const size_base_nam = baseline_nam.size().getInfo();
  const size_base_zim = baseline_zim.size().getInfo();

  print(`2019 Feb 21-28 Namibia: ${size_2019_nam} images`);
  print(`2019 Feb 21-28 Zimbabwe: ${size_2019_zim} images`);
  print(`Baseline Feb 21-28 Namibia: ${size_base_nam} images`);
  print(`Baseline Feb 21-28 Zimbabwe: ${size_base_zim} images`);

  if (size_2019_nam === 0 || size_2019_zim === 0 || size_base_nam === 0 || size_base_zim === 0) {
    print("Insufficient data for comparison.");
    print("C1");
    return;
  }

  // Calculate mean NDVI for 2019
  const ndvi_2019_nam = ls8_2019_nam.select('NDVI').mean();
  const ndvi_2019_zim = ls8_2019_zim.select('NDVI').mean();

  // Calculate baseline statistics
  const ndvi_base_nam = baseline_nam.select('NDVI');
  const ndvi_base_zim = baseline_zim.select('NDVI');

  const mean_base_nam = ndvi_base_nam.mean();
  const mean_base_zim = ndvi_base_zim.mean();

  const std_base_nam = ndvi_base_nam.reduce(ee.Reducer.stdDev());
  const std_base_zim = ndvi_base_zim.reduce(ee.Reducer.stdDev());

  // Calculate anomalies (standardized)
  const anomaly_nam = ndvi_2019_nam.subtract(mean_base_nam).divide(std_base_nam.select('NDVI_stdDev'));
  const anomaly_zim = ndvi_2019_zim.subtract(mean_base_zim).divide(std_base_zim.select('NDVI_stdDev'));

  // Get regional means
  const stats_nam = anomaly_nam.reduceRegion(
    {reducer: ee.Reducer.mean(), geometry: namibia, scale: 1000, maxPixels: 1e9}
  ).getInfo();

  const stats_zim = anomaly_zim.reduceRegion(
    {reducer: ee.Reducer.mean(), geometry: zimbabwe, scale: 1000, maxPixels: 1e9}
  ).getInfo();

  const anomaly_value_nam = stats_nam['NDVI'];
  const anomaly_value_zim = stats_zim['NDVI'];

  print(`Namibia anomaly: ${anomaly_value_nam ? anomaly_value_nam.toFixed(3) : 'None'}`);
  print(`Zimbabwe anomaly: ${anomaly_value_zim ? anomaly_value_zim.toFixed(3) : 'None'}`);

  // Validate results
  if (anomaly_value_nam === null || anomaly_value_nam === undefined || isNaN(anomaly_value_nam) ||
      anomaly_value_zim === null || anomaly_value_zim === undefined || isNaN(anomaly_value_zim)) {
    print("C3");
    return;
  }

  // Compare: worse anomaly = more negative
  if (anomaly_value_nam < anomaly_value_zim) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
